const b = $input.first().json.body || $input.first().json || {};
const userId = (b.userId || b.externalUserId || b.user_id || '').toString().trim();
if (!userId) throw new Error('ไม่พบ userId ของลูกค้า');
const keys = ['text', 'message', 'reply', 'content'];
let text = '';
for (const k of keys) {
  if (b[k] !== undefined && b[k] !== null && String(b[k]).trim() !== '') { text = String(b[k]).trim(); break; }
}
const type = ((b.messageType || b.message_type || 'text') + '').toLowerCase().replace(/[^a-z]/g, '') || 'text';
if (!text && type === 'text') throw new Error('ไม่พบข้อความ');
const q = (s) => (s === undefined || s === null) ? null : String(s);
const sq = (s) => q(s) === null ? null : q(s).replace(/'/g, "''");
const ch = (b.channel || 'line').toString();
const channel = /^[a-z0-9_]{2,32}$/.test(ch) ? ch : 'line';
const sn = (b.sender || 'customer').toString();
const sender = ['customer', 'bot', 'agent', 'system'].includes(sn) ? sn : 'customer';
const disp = b.displayName || b.display_name || null;
const pic = b.pictureUrl || b.picture_url || null;
const med = b.mediaUrl || b.media_url || null;
const prv = b.mediaPreviewUrl || b.media_preview_url || null;
const spk = b.stickerPackage || b.sticker_package || null;
const sti = b.stickerId || b.sticker_id || null;
const mid = b.messageId || b.externalMessageId || b.external_message_id || null;
const Q = (v) => v === null ? 'NULL' : ` '${v}'`;
const NQ = (v, n) => v === null ? 'NULL' : `'${v.slice(0, n)}'`;
const sql = `SELECT * FROM cd_msg_in('${channel}', '${q(userId).replace(/'/g, "''")}', '${q(text.slice(0, 8000))}', '${sender}', ${Q(sq(disp ? String(disp).slice(0,150) : null))}, ${Q(sq(pic ? String(pic).slice(0,255) : null))}, '${type}', ${NQ(sq(med ? String(med) : null), 500)}, ${NQ(sq(prv ? String(prv) : null), 500)}, ${NQ(sq(spk ? String(spk) : null), 50)}, ${NQ(sq(sti ? String(sti) : null), 50)}, ${mid ? `'${q(String(mid).slice(0,64))}'` : 'NULL'});`;
return [{ json: { sql: sql } }];

const r = $input.first().json;
return [{ json: { ok: true, conversationId: r.conversation_id, messageId: r.message_id,
  duplicate: !!r.duplicate, botEnabled: !!r.bot_enabled, displayName: r.display_name } }];
